import{_ as e,o as t,c as i,a5 as o}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 66 话 Tailwind 与原生 CSS 的边界","description":"","frontmatter":{},"headers":[],"relativePath":"comics/architecture/EP.66-tailwind-native-boundary.md","filePath":"comics/architecture/EP.66-tailwind-native-boundary.md","lastUpdated":1793853676000}'),r={name:"comics/architecture/EP.66-tailwind-native-boundary.md"};function d(n,a,l,c,s,h){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="漫画-·-第-66-话-tailwind-与原生-css-的边界" tabindex="-1">漫画 · 第 66 话 Tailwind 与原生 CSS 的边界 <a class="header-anchor" href="#漫画-·-第-66-话-tailwind-与原生-css-的边界" aria-label="Permalink to &quot;漫画 · 第 66 话 Tailwind 与原生 CSS 的边界&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/architecture/04-tailwind-native-css-boundary">docs/architecture/04-tailwind-native-css-boundary.md</a> ｜ 原画：<a href="./EP.66-tailwind-native-boundary.svg">EP.66-tailwind-native-boundary.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>标签君</strong>：结构师。本话他接手一个「全量 Tailwind」项目，发现十二个页面有十二种按钮内边距。</li><li><strong>像素酱</strong>：CSS 造型师。她主张组件契约必须回到原生 CSS，复杂状态更不该用工具类拼。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>项目把按钮、输入框、卡片都用工具类拼装。半年后三件事爆发：同一按钮在十二个页面有十二种内边距；暗色主题有十八处硬编码颜色漏改；复杂下拉状态用 <code>group-has-*</code> 堆到不可读。标签君和像素酱重新划边界：原子能力留工具类，组件契约进 <code>@layer components</code>，复杂状态回归原生 CSS。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>工具类的优势是局部与可组合，代价是一致性依赖配置与评审。当组件契约也交给工具类，每个使用点都要重复状态、焦点与禁用样式；一处需求变化，就要改遍所有模板。任意值 <code>p-[13px]</code> 则直接绕过设计约束。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>Tailwind v4 生成 <code>@layer theme, base, components, utilities</code>，工具类位于最高层，所以 <code>class=&quot;btn px-4&quot;</code> 里的 <code>px-4</code> 会覆盖 <code>.btn</code> 的内边距——这是设计行为，不是 bug。<code>@theme</code> 同时输出工具类与 CSS 变量，组件可以直接消费同一份令牌，避免两套色值。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>边界原则很简单：间距、颜色、排版等单维度调整用工具类；按钮、卡片、表单的结构、状态、变体用原生 CSS；<code>:has()</code>、容器查询、<code>@starting-style</code>、伪元素装饰回原生；主题与令牌用原生变量。结果是按钮内边距收敛为三档，暗色漏改降为零。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>工具类赢在局部可组合，组件 CSS 赢在契约集中，二者是分工不是替代。</li><li>理解层顺序：utilities 覆盖 components 是设计如此，覆盖失效先查层，不要加 <code>!important</code>。</li><li>令牌单一来源：先有令牌，再映射到工具类与组件 CSS，避免两套色值。</li><li>任意值不是禁用，而是需要评审；一次性像素值应回填到令牌。</li><li>复杂状态回归原生 CSS，可读性与可测试性都更好。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>&lt;button class=&quot;btn btn--primary px-5&quot;&gt;</code> 中，<code>px-5</code> 为什么能覆盖 <code>.btn</code> 里写的 <code>padding-inline</code>？</p><p><strong>答</strong>：因为 Tailwind 把工具类放进 <code>utilities</code> 层，而组件类在 <code>components</code> 层。分层后先比层顺序，utilities 高于 components，所以工具类胜出，与选择器特异性无关。这正是工具类做局部微调的机制；若覆盖不生效，应先检查两个类是否真的落在对应层，而不是提高特异性。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>在示例中切换「纯工具类 / 组件契约 / 分层混合」三种写法，对比维护成本与覆盖结果：<a href="./../../examples/architecture/04-tailwind-native-css">examples/architecture/04-tailwind-native-css</a></li><li>给按钮加一个 <code>px-5</code> 工具类，观察它如何覆盖组件层内边距。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>架构篇收官。第 67 话起进入质量门禁篇：《视觉回归测试》——把「看起来没变」变成可自动判定的证据。</p>',22)])])}const b=e(r,[["render",d]]);export{p as __pageData,b as default};
